-- Contracts organ -- generated by noctusai_lib.domain.contracts.sql (do not hand-edit)

SET search_path = commerce, public;

-- Contracts: one commercial agreement with a party; the billing model decides how it turns into receivables.
CREATE TABLE IF NOT EXISTS commerce.ctr_contracts (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id                  UUID NOT NULL,
    number                  TEXT,
    title                   TEXT NOT NULL CHECK (length(btrim(title)) > 0),
    party_id                UUID,
    party_name              TEXT,
    party_doc               TEXT,
    status                  TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'suspended', 'terminated', 'expired')),
    billing_model           TEXT NOT NULL CHECK (billing_model IN ('one_time', 'installments', 'recurring', 'retainer')),
    amount_cents            BIGINT NOT NULL DEFAULT 0 CHECK (amount_cents >= 0),
    frequency               TEXT CHECK (frequency IS NULL OR frequency IN ('monthly', 'quarterly', 'yearly')),
    installments_count      INTEGER CHECK (installments_count IS NULL OR installments_count BETWEEN 1 AND 120),
    due_day                 INTEGER CHECK (due_day IS NULL OR due_day BETWEEN 1 AND 31),
    first_due_date          DATE,
    next_period_on          DATE,
    start_date              DATE,
    end_date                DATE,
    auto_renew              BOOLEAN NOT NULL DEFAULT false,
    renewal_months          INTEGER NOT NULL DEFAULT 12 CHECK (renewal_months BETWEEN 1 AND 120),
    retainer_minutes        INTEGER CHECK (retainer_minutes IS NULL OR retainer_minutes >= 0),
    excess_rate_cents       BIGINT CHECK (excess_rate_cents IS NULL OR excess_rate_cents >= 0),
    readjustment_index      TEXT NOT NULL DEFAULT 'none' CHECK (readjustment_index IN ('none', 'IPCA', 'IGPM', 'INPC', 'fixed')),
    readjustment_percent_bp INTEGER CHECK (readjustment_percent_bp IS NULL OR readjustment_percent_bp BETWEEN 0 AND 100000),
    readjustment_every_months INTEGER NOT NULL DEFAULT 12 CHECK (readjustment_every_months BETWEEN 1 AND 120),
    last_readjusted_on      DATE,
    notice_days             INTEGER NOT NULL DEFAULT 0 CHECK (notice_days BETWEEN 0 AND 365),
    penalty_cents           BIGINT NOT NULL DEFAULT 0 CHECK (penalty_cents >= 0),
    penalty_bp              INTEGER NOT NULL DEFAULT 0 CHECK (penalty_bp BETWEEN 0 AND 10000),
    penalty_applied_cents   BIGINT CHECK (penalty_applied_cents IS NULL OR penalty_applied_cents >= 0),
    document_body           TEXT,
    version_n               INTEGER NOT NULL DEFAULT 1 CHECK (version_n >= 1),
    activated_at            TIMESTAMPTZ,
    suspended_at            TIMESTAMPTZ,
    suspension_reason       TEXT,
    terminated_on           DATE,
    termination_reason      TEXT,
    signature_provider      TEXT,
    signature_external_id   TEXT,
    signature_status        TEXT NOT NULL DEFAULT 'none' CHECK (signature_status IN ('none', 'pendente', 'parcial', 'concluido', 'cancelado', 'expirado')),
    signed_at               TIMESTAMPTZ,
    source_quote_id         TEXT,
    notes                   TEXT,
    created_by              UUID,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, org_id),
    CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date),
    FOREIGN KEY (party_id, org_id) REFERENCES commerce.pty_parties(id, org_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_ctr_contracts_number ON commerce.ctr_contracts (org_id, lower(number)) WHERE number IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_ctr_contracts_signature ON commerce.ctr_contracts (signature_provider, signature_external_id) WHERE signature_external_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_ctr_contracts_quote ON commerce.ctr_contracts (org_id, source_quote_id) WHERE source_quote_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ctr_contracts_org_status ON commerce.ctr_contracts (org_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ctr_contracts_org_party ON commerce.ctr_contracts (org_id, party_id) WHERE party_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ctr_contracts_due ON commerce.ctr_contracts (next_period_on) WHERE status = 'active';

ALTER TABLE commerce.ctr_contracts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "ctr_contracts_select_own_org" ON commerce.ctr_contracts;
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.ctr_contracts;
CREATE POLICY "service_role_bypass" ON commerce.ctr_contracts FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON commerce.ctr_contracts FROM PUBLIC, anon, authenticated;
GRANT ALL ON commerce.ctr_contracts TO service_role;

-- Services / items billed by the contract. `amount_cents` of the contract is the sum of its lines when it has any.
CREATE TABLE IF NOT EXISTS commerce.ctr_contract_lines (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id           UUID NOT NULL,
    contract_id      UUID NOT NULL,
    position         INTEGER NOT NULL DEFAULT 0,
    item_id          UUID,
    description      TEXT NOT NULL CHECK (length(btrim(description)) > 0),
    quantity         INTEGER NOT NULL DEFAULT 1 CHECK (quantity >= 1),
    unit_price_cents BIGINT NOT NULL CHECK (unit_price_cents >= 0),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (contract_id, org_id) REFERENCES commerce.ctr_contracts(id, org_id) ON DELETE CASCADE,
    FOREIGN KEY (org_id, item_id) REFERENCES commerce.itm_items(org_id, id)
);
CREATE INDEX IF NOT EXISTS idx_ctr_contract_lines_contract ON commerce.ctr_contract_lines (org_id, contract_id, position);

ALTER TABLE commerce.ctr_contract_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "ctr_contract_lines_select_own_org" ON commerce.ctr_contract_lines;
CREATE POLICY "ctr_contract_lines_select_own_org" ON commerce.ctr_contract_lines FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.ctr_contract_lines;
CREATE POLICY "service_role_bypass" ON commerce.ctr_contract_lines FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.ctr_contract_lines TO authenticated;
GRANT ALL ON commerce.ctr_contract_lines TO service_role;

-- Versions / amendments: every change to the terms is a new row (v1 = the initial terms), append-only.
CREATE TABLE IF NOT EXISTS commerce.ctr_contract_versions (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    contract_id UUID NOT NULL,
    version_n   INTEGER NOT NULL CHECK (version_n >= 1),
    kind        TEXT NOT NULL CHECK (kind IN ('initial', 'amendment', 'readjustment', 'renewal', 'suspension', 'resumption', 'termination')),
    summary     TEXT,
    changes     JSONB NOT NULL DEFAULT '{}'::jsonb,
    snapshot    JSONB NOT NULL DEFAULT '{}'::jsonb,
    effective_on DATE,
    created_by  UUID,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (contract_id, version_n),
    CHECK (jsonb_typeof(changes) = 'object' AND jsonb_typeof(snapshot) = 'object'),
    FOREIGN KEY (contract_id, org_id) REFERENCES commerce.ctr_contracts(id, org_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_ctr_contract_versions_contract ON commerce.ctr_contract_versions (org_id, contract_id, version_n);

ALTER TABLE commerce.ctr_contract_versions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "ctr_contract_versions_select_own_org" ON commerce.ctr_contract_versions;
CREATE POLICY "ctr_contract_versions_select_own_org" ON commerce.ctr_contract_versions FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.ctr_contract_versions;
CREATE POLICY "service_role_bypass" ON commerce.ctr_contract_versions FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.ctr_contract_versions TO authenticated;
GRANT ALL ON commerce.ctr_contract_versions TO service_role;

-- What each contract already billed (one row per finance receivable). UNIQUE (contract, period, kind) is the idempotency floor.
CREATE TABLE IF NOT EXISTS commerce.ctr_contract_billings (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id       UUID NOT NULL,
    contract_id  UUID NOT NULL,
    period_key   TEXT NOT NULL,
    kind         TEXT NOT NULL DEFAULT 'fixed' CHECK (kind IN ('fixed', 'excess', 'penalty')),
    entry_id     UUID,
    source_ref   TEXT NOT NULL,
    amount_cents BIGINT NOT NULL CHECK (amount_cents >= 0),
    due_date     DATE NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (contract_id, period_key, kind),
    FOREIGN KEY (contract_id, org_id) REFERENCES commerce.ctr_contracts(id, org_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_ctr_contract_billings_contract ON commerce.ctr_contract_billings (org_id, contract_id, due_date);

ALTER TABLE commerce.ctr_contract_billings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "ctr_contract_billings_select_own_org" ON commerce.ctr_contract_billings;
CREATE POLICY "ctr_contract_billings_select_own_org" ON commerce.ctr_contract_billings FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.ctr_contract_billings;
CREATE POLICY "service_role_bypass" ON commerce.ctr_contract_billings FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.ctr_contract_billings TO authenticated;
GRANT ALL ON commerce.ctr_contract_billings TO service_role;

-- Retainer usage log (minutes worked per month); the excess over the franchise is billed in arrears.
CREATE TABLE IF NOT EXISTS commerce.ctr_contract_usage (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id       UUID NOT NULL,
    contract_id  UUID NOT NULL,
    period_month DATE NOT NULL CHECK (period_month = date_trunc('month', period_month)::date),
    minutes      INTEGER NOT NULL CHECK (minutes > 0),
    description  TEXT,
    created_by   UUID,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (contract_id, org_id) REFERENCES commerce.ctr_contracts(id, org_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_ctr_contract_usage_contract ON commerce.ctr_contract_usage (org_id, contract_id, period_month);

ALTER TABLE commerce.ctr_contract_usage ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "ctr_contract_usage_select_own_org" ON commerce.ctr_contract_usage;
CREATE POLICY "ctr_contract_usage_select_own_org" ON commerce.ctr_contract_usage FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.ctr_contract_usage;
CREATE POLICY "service_role_bypass" ON commerce.ctr_contract_usage FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.ctr_contract_usage TO authenticated;
GRANT ALL ON commerce.ctr_contract_usage TO service_role;

-- Attachments (the signed scan, annexes). Objects live in the PRIVATE bucket; `storage_path` is server-generated.
CREATE TABLE IF NOT EXISTS commerce.ctr_contract_attachments (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id       UUID NOT NULL,
    contract_id  UUID NOT NULL,
    kind         TEXT NOT NULL DEFAULT 'other' CHECK (kind IN ('contract', 'signed', 'other')),
    storage_path TEXT NOT NULL,
    filename     TEXT NOT NULL,
    content_type TEXT NOT NULL,
    size_bytes   BIGINT NOT NULL CHECK (size_bytes >= 0),
    uploaded_by  UUID,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (contract_id, org_id) REFERENCES commerce.ctr_contracts(id, org_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_ctr_contract_attachments_contract ON commerce.ctr_contract_attachments (org_id, contract_id, created_at);

ALTER TABLE commerce.ctr_contract_attachments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "ctr_contract_attachments_select_own_org" ON commerce.ctr_contract_attachments;
CREATE POLICY "ctr_contract_attachments_select_own_org" ON commerce.ctr_contract_attachments FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.ctr_contract_attachments;
CREATE POLICY "service_role_bypass" ON commerce.ctr_contract_attachments FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON commerce.ctr_contract_attachments TO authenticated;
GRANT ALL ON commerce.ctr_contract_attachments TO service_role;

-- Finance entries admit source='contracts' (guarded: no-op while the finance organ is not mounted in this schema).
DO $contracts_src$
BEGIN
    IF to_regclass('commerce.fin_entries') IS NOT NULL THEN
        ALTER TABLE commerce.fin_entries DROP CONSTRAINT IF EXISTS fin_entries_source_check;
        ALTER TABLE commerce.fin_entries ADD CONSTRAINT fin_entries_source_check CHECK (source IN ('manual', 'recurrence', 'installment', 'commerce_order', 'contracts', 'import', 'external', 'purchasing'));
    END IF;
END
$contracts_src$;
